problems.starterCode:
async function indexLogBatches(entries, chunkSize, onChunk) {
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new RangeError('chunkSize must be a positive integer');
  }
  if (entries.length === 0) {
    return 0;
  }

  let offset = 0;
  await new Promise((resolve) => {
    function step() {
      const slice = entries.slice(offset, offset + chunkSize);
      onChunk(slice);
      offset += slice.length;
      if (offset >= entries.length) {
        resolve();
        return;
      }
      queueMicrotask(step);
    }
    step();
  });

  return entries.length;
}

module.exports = { indexLogBatches };

problems.solutionCode:
function yieldMacrotask() {
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
}

async function indexLogBatches(entries, chunkSize, onChunk) {
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new RangeError('chunkSize must be a positive integer');
  }
  if (entries.length === 0) {
    return 0;
  }

  for (let offset = 0; offset < entries.length; offset += chunkSize) {
    const slice = entries.slice(offset, offset + chunkSize);
    onChunk(slice);
    if (offset + chunkSize < entries.length) {
      await yieldMacrotask();
    }
  }

  return entries.length;
}

module.exports = { indexLogBatches };

